package week1.day2;

public class IsPrime {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
     int num=13;
     
      
    	 if (num==2||num==3) {
    		 System.out.println("prime");}
    	 else if  (num%2==0) {
    		 System.out.println("not prime");
    	 }
    	 else if (num%3==0) {
    		 System.out.println("not prime");
    	 }
    	 else
    	 {
    		 System.out.println("prime");
    	 }
	}

}
